    :root {
      --primary-gradient: linear-gradient(135deg, rgba(0, 153, 255, 0.15) 0%, rgba(0, 78, 146, 0.1) 100%);
      --hover-gradient: linear-gradient(135deg, rgba(0, 153, 255, 0.25) 0%, rgba(0, 122, 255, 0.15) 100%);
      --selected-gradient: linear-gradient(135deg, #0099ff 0%, #007aff 100%);
    }

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
      -webkit-tap-highlight-color: transparent;
    }

    html,
    body {
      height: 100%;
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
        Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
      background: linear-gradient(135deg, #0a0a23 0%, #000428 25%, #004e92 75%, #0066cc 100%);
      background-attachment: fixed;
      color: #00d4ff;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    body {
      display: flex;
      flex-direction: column;
      min-height: 100vh;
      padding-top: 120px;
      padding-bottom: 50vh;
      position: relative;
      overflow: hidden;
    }

    .background-video {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      filter: blur(20px) brightness(0.3);
      z-index: -1;
      opacity: 0;
      transition: opacity 0.5s ease;
    }

    .background-video.active {
      opacity: 1;
    }

    .header-container {
      text-align: center;
      padding: 1rem 1rem 2rem;
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      z-index: 100;
      background: linear-gradient(135deg, rgba(10, 10, 35, 0.95) 0%, rgba(0, 4, 40, 0.9) 50%, rgba(0, 78, 146, 0.85) 100%);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid rgba(0, 212, 255, 0.2);
    }

    h1 {
      font-weight: 700;
      font-size: 1.75rem;
      color: #fff;
      letter-spacing: -0.02em;
    }

    .subtitle {
      margin-top: 0.25rem;
      font-weight: 500;
      color: #00BB00;
      font-size: 1.1rem;
    }

    .appointment-btn {
      margin-top: 1rem;
      background: rgba(255, 255, 255, 0.15);
      border: 1px solid rgba(255, 255, 255, 0.3);
      color: white;
      padding: 8px 16px;
      border-radius: 12px;
      font-weight: 500;
      font-size: 0.9rem;
      cursor: pointer;
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.2);
      transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
    }

    .appointment-btn:hover {
      transform: translateY(-2px);
      background: rgba(255, 255, 255, 0.25);
      border-color: rgba(255, 255, 255, 0.5);
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
    }

    .calendar-modal {
      position: fixed;
      inset: 0;
      background: linear-gradient(135deg, rgba(10, 10, 35, 0.8) 0%, rgba(0, 4, 40, 0.85) 50%, rgba(0, 78, 146, 0.7) 100%);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      z-index: 2000;
      display: flex;
      justify-content: center;
      align-items: center;
      opacity: 0;
      visibility: hidden;
      transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }

    .calendar-modal.show {
      opacity: 1;
      visibility: visible;
    }

    .calendar-container {
      background: linear-gradient(135deg, rgba(10, 10, 35, 0.95) 0%, rgba(0, 4, 40, 0.9) 50%, rgba(0, 78, 146, 0.85) 100%);
      backdrop-filter: blur(30px) saturate(180%);
      -webkit-backdrop-filter: blur(30px) saturate(180%);
      border: 1px solid rgba(0, 212, 255, 0.3);
      border-radius: 16px;
      padding: 1.5rem;
      max-width: 400px;
      width: 90%;
      box-shadow: 0 12px 32px rgba(0, 153, 255, 0.4), 0 0 20px rgba(0, 212, 255, 0.2);
      transform: translateY(50px) scale(0.9);
      transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }

    .calendar-modal.show .calendar-container {
      transform: translateY(0) scale(1);
    }

    .calendar-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 1.5rem;
      color: white;
    }

    .calendar-header h2 {
      font-size: 1.4rem;
      font-weight: 600;
      margin: 0;
    }

    .back-btn {
      background: rgba(255, 255, 255, 0.2);
      border: none;
      color: white;
      padding: 6px 12px;
      border-radius: 8px;
      cursor: pointer;
      font-size: 0.8rem;
      transition: all 0.3s ease;
    }

    .back-btn:hover {
      background: rgba(255, 255, 255, 0.3);
      transform: translateX(-2px);
    }

    .date-selection {
      text-align: center;
    }

    .all-date-buttons {
      display: flex;
      gap: 0.5rem;
      align-items: stretch;
    }

    .quick-date-buttons {
      display: flex;
      gap: 0.5rem;
      flex: 2;
    }

    .quick-date-btn {
      flex: 1;
      background: var(--primary-gradient);
      border: 1px solid rgba(0, 212, 255, 0.3);
      border-radius: 8px;
      padding: 0.5rem 0.4rem;
      color: white;
      cursor: pointer;
      transition: all 0.3s ease;
      text-align: center;
      min-height: 60px;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .quick-date-btn:hover {
      background: var(--hover-gradient);
      border-color: #00d4ff;
      transform: translateY(-2px);
      box-shadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .quick-date-btn.selected {
      background: var(--selected-gradient);
      border-color: #00d4ff;
      box-shadow: 0 6px 16px rgba(0, 122, 255, 0.4);
    }

    .date-label {
      font-weight: 600;
      font-size: 0.9rem;
      margin-bottom: 0.25rem;
    }

    .date-value {
      font-size: 0.8rem;
      opacity: 0.8;
    }

    .calendar-open-btn {
      background: var(--primary-gradient);
      border: 1px solid rgba(0, 212, 255, 0.3);
      color: white;
      padding: 0.5rem 0.75rem;
      border-radius: 8px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.3s ease;
      font-size: 0.8rem;
      flex: 1;
      min-height: 60px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .calendar-open-btn:hover {
      background: var(--hover-gradient);
      border-color: #00d4ff;
      transform: translateY(-2px);
      box-shadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .calendar-nav {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 1rem;
    }

    .calendar-nav button {
      background: rgba(255, 255, 255, 0.2);
      border: none;
      color: white;
      width: 32px;
      height: 32px;
      border-radius: 8px;
      cursor: pointer;
      font-size: 1.2rem;
      transition: background 0.3s ease;
    }

    .calendar-nav button:hover {
      background: rgba(255, 255, 255, 0.3);
    }

    .calendar-nav h3 {
      color: white;
      margin: 0;
      font-size: 1.2rem;
    }

    .calendar-grid {
      margin-bottom: 1.5rem;
    }

    .weekdays {
      display: grid;
      grid-template-columns: repeat(7, 1fr);
      gap: 0.5rem;
      margin-bottom: 1rem;
      text-align: center;
      color: rgba(255, 255, 255, 0.7);
      font-weight: 600;
    }

    .dates-grid {
      display: grid;
      grid-template-columns: repeat(7, 1fr);
      gap: 0.5rem;
    }

    .date-cell {
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, rgba(0, 153, 255, 0.15) 0%, rgba(0, 78, 146, 0.1) 100%);
      border: 1px solid rgba(0, 212, 255, 0.2);
      border-radius: 8px;
      color: white;
      cursor: pointer;
      transition: all 0.3s ease;
      font-weight: 500;
    }

    .date-cell:hover {
      background: linear-gradient(135deg, rgba(0, 122, 255, 0.3) 0%, rgba(0, 153, 255, 0.2) 100%);
      border-color: #00d4ff;
      transform: scale(1.05);
      box-shadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .date-cell.selected {
      background: linear-gradient(135deg, #0099ff 0%, #007aff 100%);
      border-color: #00d4ff;
      box-shadow: 0 6px 16px rgba(0, 122, 255, 0.4);
    }

    .date-cell.other-month {
      color: rgba(255, 255, 255, 0.3);
    }

    .back-to-quick {
      background: linear-gradient(135deg, rgba(0, 153, 255, 0.15) 0%, rgba(0, 78, 146, 0.1) 100%);
      border: 1px solid rgba(0, 212, 255, 0.3);
      color: white;
      padding: 10px 20px;
      border-radius: 12px;
      cursor: pointer;
      transition: all 0.3s ease;
      font-size: 0.9rem;
      width: 100%;
    }

    .back-to-quick:hover {
      background: linear-gradient(135deg, rgba(0, 153, 255, 0.25) 0%, rgba(0, 122, 255, 0.15) 100%);
      border-color: #00d4ff;
      box-shadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .weekly-dates-grid {
      display: grid;
      grid-template-columns: repeat(7, 1fr);
      gap: 0.5rem;
      margin-bottom: 1.5rem;
    }

    .weekly-day-card {
      background: linear-gradient(135deg, rgba(26, 26, 58, 0.9) 0%, rgba(13, 20, 33, 0.85) 50%, rgba(30, 58, 95, 0.8) 100%);
      border: 1px solid rgba(0, 212, 255, 0.2);
      border-radius: 8px;
      padding: 0.75rem;
      cursor: pointer;
      transition: all 0.3s ease;
      text-align: center;
      min-height: 100px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .weekly-day-card:hover {
      background: linear-gradient(135deg, rgba(0, 122, 255, 0.3) 0%, rgba(0, 78, 146, 0.25) 100%);
      border-color: #00d4ff;
      transform: translateY(-2px);
      box-shadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .weekly-day-card.selected {
      background: linear-gradient(135deg, #0099ff 0%, #007aff 100%);
      border-color: #00d4ff;
      box-shadow: 0 6px 16px rgba(0, 122, 255, 0.4);
    }

    .weekly-day-card.disabled {
      opacity: 0.3;
      cursor: not-allowed;
      pointer-events: none;
    }

    .weekly-day-header {
      color: white;
      font-weight: 600;
      margin-bottom: 0.5rem;
    }

    .weekly-day-date {
      font-size: 1.2rem;
      font-weight: 700;
      color: white;
      margin-bottom: 0.5rem;
    }

    .weekly-day-slots {
      display: flex;
      flex-direction: column;
      gap: 0.25rem;
    }

    .weekly-time-slot {
      background: rgba(255, 255, 255, 0.2);
      border: none;
      color: white;
      padding: 0.25rem 0.5rem;
      border-radius: 6px;
      cursor: pointer;
      font-size: 0.8rem;
      transition: all 0.2s ease;
    }

    .weekly-time-slot:hover {
      background: rgba(255, 255, 255, 0.3);
    }

    .weekly-time-slot.selected {
      background: #34c759;
      font-weight: 600;
    }

    .selected-date-info {
      text-align: center;
      margin-bottom: 1.5rem;
      color: white;
      font-size: 1.1rem;
      font-weight: 600;
    }

    .time-slots-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1rem;
      margin-bottom: 1.5rem;
    }

    .time-slot {
      background: linear-gradient(135deg, rgba(26, 26, 58, 0.9) 0%, rgba(13, 20, 33, 0.85) 50%, rgba(30, 58, 95, 0.8) 100%);
      border: 1px solid rgba(0, 212, 255, 0.3);
      color: white;
      padding: 0.75rem;
      border-radius: 12px;
      cursor: pointer;
      transition: all 0.3s ease;
      font-weight: 500;
      font-size: 1rem;
    }

    .time-slot:hover {
      background: linear-gradient(135deg, rgba(0, 122, 255, 0.3) 0%, rgba(0, 153, 255, 0.2) 100%);
      border-color: #00d4ff;
      transform: translateY(-2px);
      box-shadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .time-slot.selected {
      background: linear-gradient(135deg, #0099ff 0%, #007aff 100%);
      border-color: #00d4ff;
      box-shadow: 0 6px 16px rgba(0, 122, 255, 0.4);
    }

    .back-to-dates {
      background: linear-gradient(135deg, rgba(0, 153, 255, 0.15) 0%, rgba(0, 78, 146, 0.1) 100%);
      border: 1px solid rgba(0, 212, 255, 0.3);
      color: white;
      padding: 10px 20px;
      border-radius: 12px;
      cursor: pointer;
      transition: all 0.3s ease;
      font-size: 0.9rem;
      width: 100%;
    }

    .back-to-dates:hover {
      background: linear-gradient(135deg, rgba(0, 153, 255, 0.25) 0%, rgba(0, 122, 255, 0.15) 100%);
      border-color: #00d4ff;
      box-shadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .slide-out-left {
      animation: slideOutLeft 2s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
    }

    .slide-out-right {
      animation: slideOutRight 2s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
    }

    .slide-out-up {
      animation: slideOutUp 2s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
    }

    .slide-out-down {
      animation: slideOutDown 2s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
    }

    @keyframes slideOutLeft {
      to {
        transform: translateX(-100vw);
        opacity: 0;
      }
    }

    @keyframes slideOutRight {
      to {
        transform: translateX(100vw);
        opacity: 0;
      }
    }

    @keyframes slideOutUp {
      to {
        transform: translateY(-100vh);
        opacity: 0;
      }
    }

    @keyframes slideOutDown {
      to {
        transform: translateY(100vh);
        opacity: 0;
      }
    }

    .cards-container {
      position: fixed;
      bottom: -50px;
      left: 0;
      width: 100%;
      padding: 1rem 0 3rem;
      background: linear-gradient(135deg, rgba(0, 78, 146, 0.9) 0%, rgba(0, 4, 40, 0.85) 50%, rgba(10, 10, 35, 0.8) 100%);
      backdrop-filter: saturate(180%) blur(20px);
      -webkit-backdrop-filter: saturate(180%) blur(20px);
      box-shadow: 0 -2px 20px rgba(0, 153, 255, 0.3);
      border-top: 1px solid rgba(0, 212, 255, 0.2);
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      -ms-overflow-style: none;
      display: flex;
      align-items: center;
      scroll-behavior: smooth;
      overscroll-behavior-x: contain;
    }

    .cards-container::-webkit-scrollbar {
      display: none;
    }

    .cards {
      display: flex;
      gap: 1rem;
      padding-left: 1rem;
    }

    .card {
      flex: 0 0 60vw;
      max-width: 240px;
      background: linear-gradient(135deg, #1a1a3a 0%, #0d1421 50%, #1e3a5f 100%);
      border: 1px solid rgba(0, 212, 255, 0.2);
      border-radius: 19px;
      box-shadow: 0 8px 24px rgba(0, 153, 255, 0.2), 0 0 0 1px rgba(0, 212, 255, 0.1);
      scroll-snap-align: center;
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      cursor: grab;
      transition: box-shadow 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94), 
                  transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94),
                  filter 0.3s ease;
      will-change: transform;
    }

    .card:active {
      cursor: grabbing;
    }

    .card:hover {
      box-shadow: 0 12px 32px rgba(0, 153, 255, 0.4), 0 0 20px rgba(0, 212, 255, 0.3);
      transform: translateY(-4px);
      border-color: rgba(0, 212, 255, 0.4);
    }

    .card-badge {
      position: absolute;
      top: 16px;
      right: 16px;
      background: #007aff;
      color: white;
      font-weight: 600;
      font-size: 0.75rem;
      padding: 6px 14px;
      border-radius: 12px;
      user-select: none;
      box-shadow: 0 2px 6px rgba(0, 122, 255, 0.4);
      z-index: 2;
    }

    .card-badge.popular {
      background: #34c759;
      box-shadow: 0 2px 6px rgba(52, 199, 89, 0.4);
    }

    .card video {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 144px;
      object-fit: cover;
      border-top-left-radius: 19px;
      border-top-right-radius: 19px;
      background-color: rgba(0, 0, 0, 0.2);
      z-index: 0;
      user-select: none;
      filter: brightness(0.9);
    }

    .card-content {
      position: relative;
      z-index: 1;
      padding: 1.2rem 1rem 1.6rem;
      margin-top: 144px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .card h3 {
      font-size: 1.3rem;
      font-weight: 700;
      color: #fff;
      margin-bottom: 0.3rem;
    }

    .card p {
      font-size: 0.95rem;
      color: #8e8e93;
      margin-bottom: 1rem;
    }

    .card-price {
      font-size: 1.5rem;
      font-weight: 700;
      color: #007aff;
      margin-bottom: 1.5rem;
    }

    .card button {
      background: #007aff;
      border: none;
      padding: 0.5rem 0;
      border-radius: 12px;
      color: white;
      font-weight: 500;
      font-size: 0.9rem;
      box-shadow: 0 3px 6px rgba(0, 122, 255, 0.3);
      cursor: pointer;
      transition: background-color 0.3s ease, transform 0.2s ease;
    }

    .card button:hover {
      background: #005ecb;
      transform: translateY(-2px);
    }

    .card button:active {
      background: #004bb5;
      transform: translateY(0);
    }

    .payment-info-modal {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      justify-content: center;
      align-items: center;
      z-index: 1000;
      padding: 1rem;
    }

    .payment-info-content {
      background: #1c1c1e;
      border-radius: 24px;
      max-width: 400px;
      width: 100%;
      padding: 2rem;
      color: #fff;
      box-shadow: 0 12px 36px rgba(0, 0, 0, 0.3);
      position: relative;
      animation: modalFadeIn 0.3s ease forwards;
      text-align: center;
    }

    @keyframes modalFadeIn {
      from {
        opacity: 0;
        transform: translateY(20px);
      }

      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .close {
      position: absolute;
      top: 16px;
      right: 16px;
      font-size: 1.5rem;
      color: #8e8e93;
      cursor: pointer;
      user-select: none;
      transition: color 0.3s ease;
      z-index: 2;
    }

    .close:hover {
      color: #fff;
    }

    .payment-info-content h3 {
      font-weight: 700;
      font-size: 1.4rem;
      margin-bottom: 1rem;
    }

    .payment-info-content p {
      color: #8e8e93;
      margin-bottom: 1.5rem;
      line-height: 1.5;
    }

    .bank-redirect-btn {
      background: #007aff;
      border: none;
      color: white;
      padding: 0.75rem 2rem;
      border-radius: 12px;
      font-weight: 600;
      cursor: pointer;
      font-size: 1rem;
      box-shadow: 0 3px 6px rgba(0, 122, 255, 0.3);
      transition: background-color 0.3s ease, transform 0.2s ease;
      width: 100%;
      margin-bottom: 1rem;
    }

    .bank-redirect-btn:hover {
      background: #005ecb;
      transform: translateY(-2px);
    }

    .bank-redirect-btn:active {
      background: #004bb5;
      transform: translateY(0);
    }

    .toast {
      position: fixed;
      bottom: 20px;
      left: 50%;
      transform: translateX(-50%) translateY(100px);
      background-color: #007aff;
      color: white;
      padding: 12px 24px;
      border-radius: 50px;
      z-index: 2000;
      box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
      opacity: 0;
      transition: transform 0.3s, opacity 0.3s;
      font-weight: 600;
      font-size: 1rem;
    }

    .toast.show {
      transform: translateX(-50%) translateY(0);
      opacity: 1;
    }

    @media (min-width: 768px) {
      .card {
        flex: 0 0 208px;
        max-width: 208px;
      }
    }

    @media (min-width: 1200px) {
      .card {
        flex: 0 0 224px;
        max-width: 224px;
      }
    }
  </style>
</head>

<body>
  <video class="background-video" id="bg-video-0" autoplay muted loop playsinline webkit-playsinline>
    <source src="" type="video/mp4" />
  </video>
  <video class="background-video" id="bg-video-1" autoplay muted loop playsinline webkit-playsinline>
    <source src="" type="video/mp4" />
  </video>
  <video class="background-video" id="bg-video-2" autoplay muted loop playsinline webkit-playsinline>
    <source src="" type="video/mp4" />
  </video>

  <div class="header-container">
    <h1>Zoltán Dalma</h1>
    <div class="subtitle">Válaszd ki a csomagod</div>
    <button class="appointment-btn" onclick="showCalendar()" aria-label="Időpont foglaláshoz katt ide!">
      📅 Időpont foglaláshoz katt ide!
    </button>
  </div>

  <div id="calendar-modal" class="calendar-modal">
    <div class="calendar-container">
      <div class="calendar-header">
